import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"28、【大过】 巽下兑上","description":"子夏易传 - 28、【大过】 巽下兑上","frontmatter":{"title":"28、【大过】 巽下兑上","description":"子夏易传 - 28、【大过】 巽下兑上"},"headers":[],"relativePath":"zh/classics/zixia/030.md","filePath":"zh/classics/zixia/030.md"}'),i={name:"zh/classics/zixia/030.md"};function r(_,p,c,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="_28、【大过】-巽下兑上" tabindex="-1">28、【大过】 巽下兑上 <a class="header-anchor" href="#_28、【大过】-巽下兑上" aria-label="Permalink to “28、【大过】 巽下兑上”">​</a></h1><p>卦辞：大過，棟橈，利有攸往，亨。</p><p>彖曰：大過，大者過也。棟橈，本末弱也。剛過而中，巽而説行，利有攸往，乃亨。大過之時，大矣哉。</p><p>子夏：大過，強大者能過也。本無正，而末不能治者也。棟既橈矣，法無從矣，何所承乎。唯強行者，不拘於細，不守其弊，過之而後治也。下剛過中，上巽而後悦，行利往而後乃亨。從大然後過也，非才大者不能行。權而合悦也。</p><p>象曰：澤滅木，大過。君子以獨立不懼遯世，无悶。</p><p>子夏：木為澤所没，下過其上也。本無政矣，舉而治之亦無患也。故君子當於是，獨立而濟，不懼羣邪，然後能通，過上乃行。雖曰得之不足以榮也。遭其用，遯世無悶，失之不足恥也。</p><p>初六，藉用白茅，无咎。</p><p>象曰：藉用白茅，柔在下也。</p><p>子夏：君子之於大過也，必本於誠敬然後濟之也。雖曰藉用白茅，薄之至而誠之著也。柔處於下，謹敬於初，不私於己，則動而無咎矣。</p><p>九二，枯楊生稊，老夫得其女妻，无不利。</p><p>象曰：老夫女妻，過以相與也。</p><p>子夏：陽舉於陰，過初之本事，過其位。剛而得中，行權以合説也。老夫重合女妻，枯而復生，其實時過而相與得復生之理。故其無不利也。</p><p>九三，棟橈。凶。</p><p>象曰：棟橈之凶，不可以有輔也。</p><p>子夏：不能拯弱自守其位，棟之橈也。而又應柔本末弱矣。柔何輔焉，凶之道也。</p><p>九四，棟隆吉。有它。吝。</p><p>象曰：棟隆之吉，不橈乎下也。</p><p>子夏：以陽而與，其柔志在拯時也。得其吉矣。情以求應，不撓於下也。不能自與。可惜也已。</p><p>九五，枯楊生華，老婦得其士夫，无咎无譽。</p><p>象曰：枯楊生華，何可久也。</p><p>子夏：老婦士夫亦可醜也。陽處陽也，自守而已，不能大過者也。雖欲拯之其能得乎，不足以濟衰也。則老婦得其士夫，猶枯而徒華，可醜而已，當尊而徳不能濟，力而不能勝也。無功可譽，亦無咎矣。</p><p>上六，過涉滅頂，凶，无咎。</p><p>象曰：過涉之凶，不可咎也。</p><p>子夏：過涉襄危之極，罪咎之地也。況以柔終乎。過涉之深，滅其頂，頂滅身之終也，於何而咎哉。</p>',24)])])}const m=a(i,[["render",r]]);export{h as __pageData,m as default};
